    main()

import sys

def main():
    # Read all input from standard input
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    # Read N and D
    try:
        N = int(next(iterator))
        D = int(next(iterator))
    except StopIteration:
        return

    # Read the snakes' thickness and length
    snakes = []
    for _ in range(N):
        T = int(next(iterator))
        L = int(next(iterator))
        snakes.append((T, L))

    # For each k from 1 to D, find the maximum weight
    for k in range(1, D + 1):
        max_weight = 0
        for T, L in snakes:
            # Weight = thickness * (length + k)
            weight = T * (L + k)
            if weight > max_weight:
                max_weight = weight
        print(max_weight)

if __name__ == '__main__':
    main()

